package org.kanger;
import java.util.*;
import org.kanger.ContextDependentCutInspection.*;
import org.kanger.ContextDependentRuntimeExecution.*;
import org.kanger.ContextDependentRuntimeExecution.Request;
import org.kanger.ContextDependentRuntimeExecution.Step;
import org.kanger.ContextDependentProductionInspection.Kind;
import org.kanger.ContextDependentModelInspection.Function;
import org.kanger.ContextProductionCapture.*;

/** Substitution-certificate verifier. No unification, model evaluation or execution term builder. */
final class ContextDependentRuntimeExecutionAudit {
    final Member child;final List<Cut> cuts;final ContextDependentRuntimeInspection.Frame frame;final Request request;final Runnable work;final Map<Function,Integer> functions=new HashMap<>();int nodes;
    ContextDependentRuntimeExecutionAudit(Member child,List<Cut> cuts,ContextDependentRuntimeInspection.Frame frame,Request request)throws Exception{this.child=child;this.cuts=cuts;this.frame=frame;this.request=request;work=ContextGroundProductionRounds.budget(request.auditWork);List<Member> members=new ArrayList<>();members.add(child);for(Cut cut:cuts)members.addAll(cut.members);for(Member m:members)for(ContextProductionInventory.Row row:m.inventory.primary){work.run();org.kanger.units.Rule rule=(org.kanger.units.Rule)m.actual.getRules().get(row.nativeRule);if(NativeDependentProductionRows.unit(rule)){NativePrenexUnitScope p=NativePrenexUnitScope.observeFactoryRow(row.nativeRule,m.actual,work);Source source=new Source(m.inventory.context,m.inventory.revision,row.nativeRule,m.inventory.localX,"inventory:"+m.inventory.fingerprint);for(int i=0;i<p.binders.size();i++){work.run();if(!p.binders.get(i).universal)functions.put(new Function(source,i),p.binders.get(i).precedingUniversals.size());}}}}
    private void need(boolean b,String why){ContextDependentRuntimeExecution.need(b,why);}
    private static final class Pair {final int a,b;Pair(int a,int b){this.a=a;this.b=b;}}
    private void index(Output o,int id){work.run();need(id>=0&&id<o.nodes.size(),"Certificate graph index in range");}
    private void equal(Output o,int left,int right){Deque<Pair> todo=new ArrayDeque<>();todo.push(new Pair(left,right));Set<Long> seen=new HashSet<>();while(!todo.isEmpty()){work.run();Pair p=todo.pop();index(o,p.a);index(o,p.b);if(!seen.add(((long)p.a<<32)|(p.b&0xffffffffL)))continue;Node a=o.nodes.get(p.a),b=o.nodes.get(p.b);need(a.kind==b.kind,"Certificate substituted term kind differs");if(a.kind==Kind.VARIABLE)need(a.variable==b.variable,"Certificate variable correlation differs");else if(a.kind==Kind.VALUE)need(a.value.semanticallyEquals(b.value),"Certificate typed value differs");else{need(a.binder==b.binder&&a.function.equals(b.function)&&a.arguments.size()==b.arguments.size(),"Certificate function Source/binder/rank differs");for(int i=0;i<a.arguments.size();i++){work.run();todo.push(new Pair(a.arguments.get(i),b.arguments.get(i)));}}}}
    private void graph(Output o)throws Exception{
        List<Integer> roots=new ArrayList<>(o.arguments);for(List<Integer> r:o.literals){work.run();roots.addAll(r);}for(List<Integer> r:o.donors){work.run();roots.addAll(r);}roots.addAll(o.ruleBindings.values());for(Map<Integer,Integer> b:o.donorBindings){work.run();roots.addAll(b.values());}boolean[] seen=new boolean[o.nodes.size()];Deque<Integer> todo=new ArrayDeque<>(roots);while(!todo.isEmpty()){work.run();int id=todo.pop();index(o,id);if(seen[id])continue;seen[id]=true;for(int arg:o.nodes.get(id).arguments){work.run();need(arg>=0&&arg<id,"Certificate graph must be topological");todo.push(arg);}}
        for(int i=0;i<o.nodes.size();i++){work.run();need(++nodes<=request.nodes&&seen[i],"Whole reachable certificate graph bound");Node n=o.nodes.get(i);if(n.kind==Kind.VARIABLE)need(n.variable>=0&&n.value==null&&n.function==null&&n.binder==-1&&n.arguments.isEmpty(),"Certificate variable shape");else if(n.kind==Kind.VALUE)need(n.value!=null&&SemanticTermSnapshot.isOrdinaryValue(n.value.materialize())&&n.function==null&&n.binder==-1&&n.arguments.isEmpty(),"Certificate ordinary value shape");else{need(n.kind==Kind.APPLICATION&&n.value==null&&n.function!=null&&o.sources.contains(n.function),"Certificate function ancestry");Integer rank=functions.get(new Function(n.function,n.binder));need(rank!=null&&rank==n.arguments.size(),"Certificate actual declaration/rank");}}
    }
    private void original(Output o,Clause clause){need(o.literals.size()==clause.literals.size(),"Whole instantiated native clause required");Set<Integer> variables=new LinkedHashSet<>();for(int i=0;i<clause.literals.size();i++){work.run();ContextProductionCapture.Atom atom=clause.literals.get(i);List<Integer> roots=o.literals.get(i);need(roots.size()==atom.arguments.size(),"Native literal argument rank");for(int j=0;j<roots.size();j++){work.run();Slot slot=atom.arguments.get(j);int id=roots.get(j);index(o,id);if(slot.variable>=0){variables.add(slot.variable);Integer binding=o.ruleBindings.get(slot.variable);need(binding!=null,"Every original rule variable needs a substitution certificate");equal(o,binding,id);}else{Node node=o.nodes.get(id);need(node.kind==Kind.VALUE&&node.value.semanticallyEquals(slot.value),"Native constant must remain exact typed value");}}}need(variables.equals(o.ruleBindings.keySet()),"Exact original rule variable manifest");}
    private void donor(Output o,int donor,ContextDependentRuntimeExecution.Input input){Map<Integer,Integer> bindings=o.donorBindings.get(donor);need(ContextDependentRuntimeExecution.variables(input,work).equals(bindings.keySet()),"Exact fresh donor variable manifest");List<Integer> roots=o.donors.get(donor);need(roots.size()==input.arguments.size(),"Whole instantiated donor tuple required");Deque<Pair> todo=new ArrayDeque<>();for(int i=0;i<roots.size();i++)todo.push(new Pair(input.arguments.get(i),roots.get(i)));Set<Long> seen=new HashSet<>();while(!todo.isEmpty()){work.run();Pair p=todo.pop();index(o,p.b);if(!seen.add(((long)p.a<<32)|(p.b&0xffffffffL)))continue;Node a=input.nodes.get(p.a),b=o.nodes.get(p.b);if(a.kind==Kind.VARIABLE){Integer mapped=bindings.get(a.variable);need(mapped!=null,"Every input variable instantiated");equal(o,mapped,p.b);}else if(a.kind==Kind.VALUE)need(b.kind==Kind.VALUE&&a.value.semanticallyEquals(b.value),"Donor typed constant changed");else{need(b.kind==Kind.APPLICATION&&a.binder==b.binder&&a.function.equals(b.function)&&a.arguments.size()==b.arguments.size(),"Donor function graph changed");for(int i=0;i<a.arguments.size();i++){work.run();todo.push(new Pair(a.arguments.get(i),b.arguments.get(i)));}}}}
    /** Direct native unit/certificate comparison; never calls the executor's unit graph builder. */
    private void nativeDonor(Output o,int donor,ContextDependentRuntimeExecution.NativeUnit unit){
        Map<Integer,Integer> bindings=o.donorBindings.get(donor);List<Integer> roots=o.donors.get(donor);need(roots.size()==unit.arity(),"Whole original native donor tuple required");Set<Integer> variables=new LinkedHashSet<>();
        for(int i=0;i<roots.size();i++){work.run();int root=roots.get(i);index(o,root);
            if(unit.prefix==null){Slot slot=unit.atom.arguments.get(i);if(slot.variable>=0){variables.add(slot.variable);Integer mapped=bindings.get(slot.variable);need(mapped!=null,"Original signed unit variable binding required");equal(o,mapped,root);}else{Node node=o.nodes.get(root);need(node.kind==Kind.VALUE&&node.value.semanticallyEquals(slot.value),"Original signed unit typed constant changed");}}
            else{NativePrenexUnitScope.Slot slot=unit.prefix.slots.get(i);if(slot.binder<0){Node node=o.nodes.get(root);need(node.kind==Kind.VALUE&&node.value.semanticallyEquals(slot.value),"Original positive unit typed constant changed");continue;}NativePrenexUnitScope.Binder binder=unit.prefix.binders.get(slot.binder);if(binder.universal){variables.add(slot.binder);Integer mapped=bindings.get(slot.binder);need(mapped!=null,"Original universal unit binding required");equal(o,mapped,root);}else{Node node=o.nodes.get(root);need(node.kind==Kind.APPLICATION&&unit.source.equals(node.function)&&node.binder==slot.binder&&node.arguments.size()==binder.precedingUniversals.size(),"Exact original native witness Source/binder/dependency rank required");for(int j=0;j<binder.precedingUniversals.size();j++){work.run();int dependency=binder.precedingUniversals.get(j);variables.add(dependency);Integer mapped=bindings.get(dependency);need(mapped!=null,"Every preceding universal witness dependency required");equal(o,mapped,node.arguments.get(j));}}}
        }need(variables.equals(bindings.keySet()),"Exact reachable original-unit universal variable manifest required");
    }
    void check(List<Output> outputs)throws Exception{
        need(outputs.size()==request.steps.size(),"Whole execution plan certificate required");List<Output> checked=new ArrayList<>();for(int n=0;n<outputs.size();n++){ContextDependentRuntimeExecution.interrupt();work.run();Output o=outputs.get(n);Step step=request.steps.get(n);ContextDependentRuntimeExecution.Entry entry=ContextDependentRuntimeExecution.entry(child,cuts,step,work);ContextProductionCapture.Atom head=entry.clause.literals.get(step.retainedLiteral);need(o.cut.equals(step.cut)&&o.producer.equals(entry.source)&&o.retainedLiteral==step.retainedLiteral&&o.predicate.equals(head.predicate)&&o.positive==head.positive&&o.donors.size()==step.donors.size()&&o.donorBindings.size()==o.donors.size(),"Exact execution step metadata");graph(o);original(o,entry.clause);need(o.arguments.equals(o.literals.get(step.retainedLiteral)),"Conclusion must be the substituted retained literal");Set<Source> sources=new LinkedHashSet<>();sources.add(entry.source);int depth=0,at=0;
            for(int i=0;i<entry.clause.literals.size();i++)if(i!=step.retainedLiteral){work.run();ContextDependentRuntimeExecution.Donor selected=step.donors.get(at);ContextProductionCapture.Atom literal=entry.clause.literals.get(i);
                if(selected.original!=null){ContextDependentRuntimeExecution.NativeUnit unit=ContextDependentRuntimeExecution.unit(child,cuts,step.cut,selected.original,work);need(unit.positive()!=literal.positive&&unit.predicate().equals(literal.predicate)&&unit.arity()==literal.arguments.size(),"Original native unit must oppose its pivot");nativeDonor(o,at,unit);sources.add(unit.source);}
                else{ContextDependentRuntimeExecution.Input input=ContextDependentRuntimeExecution.input(frame,checked,step,selected,work);need(input.positive!=literal.positive&&input.predicate.equals(literal.predicate)&&input.arguments.size()==literal.arguments.size(),"Every donor must oppose its original pivot");donor(o,at,input);for(Source source:input.sources){work.run();sources.add(source);}depth=Math.max(depth,input.depth);}
                List<Integer> pivot=o.literals.get(i),actual=o.donors.get(at);for(int j=0;j<pivot.size();j++)equal(o,pivot.get(j),actual.get(j));at++;}
            need(sources.equals(o.sources)&&o.depth==depth+1&&depth<request.preparation.projection.qualification.append.iteration.policy.steps,"Whole exact original ancestry and 1+max donor depth required");checked.add(o);
        }
    }
}
